&lt;li style=&quot;padding: 10px 0; border-bottom: 1px solid #fecaca; font-size: 14.5px; line-height: 1.6;&quot;&gt;&lt;strong style=&quot;color: #991b1b;&quot;&gt;64GB base:&lt;/strong&gt; lota rápido com jogos; exige microSD&lt;/li&gt;
&lt;li style=&quot;padding: 10px 0; font-size: 14.5px; line-height: 1.6;&quot;&gt;&lt;strong style=&quot;color: #991b1b;&quot;&gt;Preço maior:&lt;/strong&gt; R$ 100-400 a mais que o Multi com menos RAM&lt;/li&gt;
